{
  "concepts": [
    {
      "conditions": [],
      "definition": "A Product-owned accepted declaration of the shared frame set for finite actors collectively engaging one governed Product scope or outcome. It binds an exact Reference Frame Method and optional profile, admitting authorities and scopes, declarations and evaluation inventory, actor bindings and capability envelopes, semantic/evaluation/operation/decision grants, result/conjunction/translation/coverage relations, and lifecycle activation and invalidation law.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 830,
          "quote": "A **Project Reference-Frame Basis** is the Product-owned accepted declaration\nof the shared frame set through which finite actors collectively engage one\ngoverned Product scope or outcome.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FSTDO%20Product%20Definition%20Overlay%20And%20Layout%20Independence%2FCollective%20Reference-Frame%20Basis",
          "start_line": 818
        }
      ],
      "key": "project_reference_frame_basis",
      "label": "Project Reference-Frame Basis"
    },
    {
      "conditions": [],
      "definition": "An execution-scoped binding of one agent to an applicable frame declaration or active configuration, exact evaluation, subject, basis, evidence boundary and capability envelope, carried by a ticket or other authorized work instruction. Frames and actors are separate identities.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 868,
          "quote": "An **Agent Frame Activation**\nis the execution-scoped binding of one agent",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FSTDO%20Product%20Definition%20Overlay%20And%20Layout%20Independence%2FCollective%20Reference-Frame%20Basis",
          "start_line": 861
        }
      ],
      "key": "agent_frame_activation",
      "label": "Agent Frame Activation"
    },
    {
      "conditions": [],
      "definition": "The common constitutional WHAT is a requirements calculus stating admissible states, outcomes, constraints, evidence obligations and permitted changes without selecting every execution means. what.intent, what.product and what.specification locate it.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 914,
          "quote": "The common `WHAT` is the requirements calculus",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FSTDO%20Product%20Definition%20Overlay%20And%20Layout%20Independence%2FWHAT%2C%20HOW%2C%20And%20Work%20Carriers",
          "start_line": 912
        }
      ],
      "key": "constitutional_what",
      "label": "Constitutional WHAT"
    },
    {
      "conditions": [],
      "definition": "A build tenant is one independent project-owned HOW realization of a common WHAT. Build tenancy is the one-or-more realization relation; multiple independent realizations constitute multi-build-tenancy. Tenant design supplies computational operations, composition, actors or mechanisms, permitted effects, operational assumptions and observation bindings. The canonical how.build_tenants Tenant Registry records stable identities and root/design/implementation locators; how.common binds realization law explicitly adopted across more than one tenant.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 910,
          "quote": "A\n**build tenant** is one such realization.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FSTDO%20Product%20Definition%20Overlay%20And%20Layout%20Independence%2FWHAT%2C%20HOW%2C%20And%20Work%20Carriers",
          "start_line": 907
        }
      ],
      "key": "build_tenancy",
      "label": "Build tenancy and its registry"
    },
    {
      "conditions": [],
      "definition": "Recursive discovery finds stdo_*.json definitions within a selected workspace, including its root and arbitrarily deep project roots. Explicit directed composition relates otherwise independent definitions through a target locator, expected stable definition identity, relation authority and one or more governing contracts.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 983,
          "quote": "Parent and child definitions remain independent until\n`composition` explicitly relates them.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FSTDO%20Product%20Definition%20Overlay%20And%20Layout%20Independence%2FRecursive%20Discovery%20And%20Explicit%20Composition",
          "start_line": 973
        }
      ],
      "key": "definition_discovery_composition",
      "label": "Definition discovery and explicit composition"
    },
    {
      "conditions": [],
      "definition": "Semantic conformance under an exact selected basis covers uniquely resolved local use, authorized cross-context relations and material collisions. Names such as Frame, Owner, Product, Tenant and User can denote distinct context-bound concepts.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1026,
          "quote": "Conformance covers both uniquely resolved use and material collision.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FSTDO%20Product%20Definition%20Overlay%20And%20Layout%20Independence%2FSemantic-Resolution%20Conformance%20Cases",
          "start_line": 1025
        }
      ],
      "key": "semantic_resolution",
      "label": "Semantic-resolution conformance"
    },
    {
      "conditions": [],
      "definition": "STDO-SURFACE-001 selects one complete released method cut and one owning standard per law. A released cut has an exact member set, member digests, review basis, human acceptance and immutable identity. Other standards consume laws by reference; derived, evidential and authoring surfaces do not constitute selectable partial constitutions.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1063,
          "quote": "The shared methodology is modular in authorship and singular in authority.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FOne%20Constitutional%20Surface%20And%20Version%20Boundary%20%28%60STDO-SURFACE-001%60%29",
          "start_line": 1055
        }
      ],
      "key": "released_constitution",
      "label": "Complete released constitutional surface"
    },
    {
      "conditions": [],
      "definition": "The homeostatic chain runs Goals → Intent → Product Definition → Requirements → Design → Realisation → Observations → Projection → Delta → Scenarios → Gap Analysis → intake-selected re-entry or observation. Goals express current work concerns; Intent purpose and direction; Product Definition mutable current realization, terms and end-state shape; Requirements invariant obligations; Design structural choices, interfaces, carriers and topology; Realisation their concrete embodiment; Observations boundary-bound occurrences and state; Projection question-relevant observations; Delta intended/realized drift; Scenarios operational tests; Gap Analysis insufficiencies exposed by use. ADRs are durable design records, not a higher constitutional layer.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1131,
          "quote": "Goals → Intent → Product Definition → Requirements → Design → Realisation → Observations → Projection → Delta",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FConstitutional%20Chain",
          "start_line": 1102
        }
      ],
      "key": "constitutional_chain",
      "label": "Constitutional chain"
    },
    {
      "conditions": [],
      "definition": "A sprint is a bounded execution-control surface under existing constitutional authority, not a new constitutional layer. It can batch and coordinate work, price proof cost and force close review. Deferred compliance is escrow; sprint close is forensic reconciliation rather than automatic approval.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1168,
          "quote": "A sprint is a bounded execution-control surface.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FSprint%20Execution%20Boundary",
          "start_line": 1166
        }
      ],
      "key": "sprint",
      "label": "Sprint execution and compliance escrow"
    },
    {
      "conditions": [],
      "definition": "SPEC_METHOD owns urn:stdo:bounded-context:ambiguity-governance. Major ambiguity materially changes architecture, stack, Product boundary, execution/deployment admissibility, public contracts or downstream realization law; micro ambiguity remains within governed design. Lawful Probabilistic Processing is policy-permitted bounded non-human handling of declared ambiguity; Human Adjudication is authority-admitted explicit human judgment where policy or risk appetite requires it. Resolved, carried forward, escalated and blocked are handling annotations, separate from claim verdicts.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1278,
          "quote": "Ambiguity detection is mandatory. Blocking is policy.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FAmbiguity%20Governance%20Rule",
          "start_line": 1270
        }
      ],
      "key": "ambiguity_governance",
      "label": "Ambiguity governance and handling"
    },
    {
      "conditions": [],
      "definition": "Every material Product, application, module, graph function, runtime/plugin/public/data surface or capability has an operational lifecycle: intent → requirement → build → assurance → release → deployment → live usage → observed telemetry → retirement.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1351,
          "quote": "The canonical operational lifecycle chain is:",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FOperational%20Lifecycle%20Sufficiency%20Rule",
          "start_line": 1339
        }
      ],
      "key": "operational_lifecycle",
      "label": "Operational lifecycle"
    },
    {
      "conditions": [],
      "definition": "Substantive change has one intake route that determines impact and lawful constitutional re-entry. Minimum classes are goal_reprice, intent_reprice, product_reprice, requirement_reprice, design_reframe and realization_refactor. Report labels, severity and priority are distinct from diagnosis and repair authority.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1384,
          "quote": "Every substantive change begins with intake triage, an explicit declared change\nintent, and a lawful re-entry point into the constitutional chain.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FChange%20Management%20Rule",
          "start_line": 1383
        },
        {
          "end_line": 1473,
          "quote": "The minimum lawful change classes are:",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FChange%20Management%20Rule%2FUniversal%20Intake%20Triage",
          "start_line": 1466
        }
      ],
      "key": "change_intake",
      "label": "Substantive change intake and re-entry"
    },
    {
      "conditions": [
        "Assurance or intake requires causal diagnosis of a counterexample on a declared path."
      ],
      "definition": "Localization identifies the earliest supported causal frontier: the causally minimal violated owner relations or seam coordinates, not the earliest log or clock entry. Its forms are a unique locus, a jointly necessary set of incomparable earliest loci, unresolved alternative frontiers, or indeterminate inability to bound a frontier.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1502,
          "quote": "earliest means\nminimal under the declared causal relation, not first in log or clock order.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FChange%20Management%20Rule%2FCounterexample%20Localization",
          "start_line": 1492
        }
      ],
      "key": "causal_localization",
      "label": "Counterexample causal localization"
    },
    {
      "conditions": [],
      "definition": "A reusable intake classification distinguishes C, reproducible facts and declared rule application; J, residual semantic or materiality judgment; and O, rulings reserved to actual owners. These are annotations, not authority grants, calculus kinds, runtimes, classifier interfaces or mandatory documents. Computed classification exposes authority traversal, Public delta, accepted-design coverage and rule-determined treatment.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1538,
          "quote": "`C` denotes reproducible facts and declared\nrule application; `J` denotes residual semantic or materiality judgment; `O`\ndenotes a ruling reserved to its actual owner.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FChange%20Management%20Rule%2FComputed%20Classification%20And%20Treatment",
          "start_line": 1534
        }
      ],
      "key": "computed_classification",
      "label": "Computed classification, residual judgment and owner ruling"
    },
    {
      "conditions": [],
      "definition": "A consistency gate evaluates closure of a declared change span as the conjunction of applicable obligations and required judgments or rulings, with no active non-closure condition. This closure predicate differs from a local artifact's fitness.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1633,
          "quote": "No gate may close while the affected active surfaces are internally inconsistent.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FConsistency%20Gate%20Rule",
          "start_line": 1627
        }
      ],
      "key": "consistency_gate",
      "label": "Consistency gate"
    },
    {
      "conditions": [],
      "definition": "A Product-outcome-bearing work wave selects one unresolved, directly verifiable Product-defined outcome instance and acceptance interval. Material advance, prerequisite readiness, preservation and regression are progress annotations on distinct predicates. Named bounded prerequisites and decision-discriminating experiments are provisional work bases; accepted outcome instances and exhausted bases do not authorize continued growth.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1667,
          "quote": "Every Product-outcome-bearing work wave identifies one explicitly selected,\nunresolved, directly verifiable Product-defined outcome and declares the\nacceptance interval for that instance.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FProduct%20Outcome%20Conservation%20%28%60STDO-UP-013%60%29",
          "start_line": 1664
        }
      ],
      "key": "product_outcome_basis",
      "label": "Product outcome and bounded work basis"
    },
    {
      "conditions": [],
      "definition": "Proportionality relates semantic ambiguity removed to effective reasoning complexity introduced. Complexity includes independent concepts and authorities, document joins, exceptions, branching, states, transitions, duplicate representations and decision-relevant detail; it is not raw line count, artifact count or context-window size.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1766,
          "quote": "Proportionality is the relation between semantic ambiguity removed and\neffective reasoning complexity introduced.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FProportional%20Method%20And%20Delivery%20%28%60STDO-UP-014%60%29",
          "start_line": 1752
        }
      ],
      "key": "method_proportionality",
      "label": "Method proportionality and delivery priority"
    },
    {
      "conditions": [
        "A selected outcome, delegated affected cone, concrete execution binding and separately bound assessment and decision authority exist."
      ],
      "definition": "UP-020 describes outcome-driven construction: accepted governing basis → bounded affected relations → selected computational relations → delegated execution and decision authority → construction/self-review → independent live assessment where required → accept/local repair/re-enter/reject → exact accepted checkpoint → next already-authorized bounded action. Construction availability, cone preservation, disposition decision, checkpoint acceptance and Product progress are distinct claims.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1860,
          "quote": "  -> accept | local repair | re-enter | reject",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FAgentic%20Construction%20Execution%20%28%60STDO-UP-020%60%29",
          "start_line": 1857
        }
      ],
      "key": "agentic_construction",
      "label": "Agentic construction execution"
    },
    {
      "conditions": [],
      "definition": "The execution unit is the smallest coherent causal dependency cone capable of delivering selected behavior while preserving every affected governing relation; its material seams follow support rather than file, function, module, ticket or document boundaries.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1890,
          "quote": "the\nsmallest coherent causal dependency cone capable of delivering the selected\nbehavior while preserving every affected governing relation.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FAgentic%20Construction%20Execution%20%28%60STDO-UP-020%60%29%2FBounded%20Causal%20Construction",
          "start_line": 1887
        }
      ],
      "key": "causal_cone",
      "label": "Bounded causal construction cone"
    },
    {
      "conditions": [],
      "definition": "Complete enclosing-relation admission assesses whether an exact candidate satisfies the complete declared transition at the current authoritative basis. Its support universe includes every participant and equality join materially affecting or affected by identity, validity, authority, currentness or transition. Assessed admitted/refused/effect-free re-entry outcomes, authorized decisions, actual semantic commit and atomicity are separate.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 2090,
          "quote": "The admission assessment predicate is `this exact candidate satisfies the\ncomplete declared transition relation at the current authoritative basis`.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FComplete%20Enclosing-Relation%20Admission%20%28%60STDO-UP-021%60%29",
          "start_line": 2086
        }
      ],
      "key": "enclosing_admission",
      "label": "Complete enclosing-relation admission"
    },
    {
      "conditions": [],
      "definition": "A core interface migration changes a load-bearing shared contract, carrier, resolver, provider, projection law, closure law or equivalent dependency. Inside-Out Hard-Break Migration replaces authority in place on one implementation line; Fundamental Re-Adoption Migration re-derives a major rewrite on a materially different basis and moves predecessor implementation to non-authoritative reference material. Product-slice promotion and complete migration closure are distinct.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 2196,
          "quote": "Core interface changes are not ordinary local patches.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FCore%20Interface%20Migration%20Rule",
          "start_line": 2191
        },
        {
          "end_line": 2232,
          "quote": "Core interface and major implementation replacement work has two lawful\nconstitutional strategies:",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FCore%20Interface%20Migration%20Rule%2FConstitutional%20Migration%20Options",
          "start_line": 2221
        }
      ],
      "key": "core_interface_migration",
      "label": "Core interface migration"
    },
    {
      "conditions": [],
      "definition": "A shared contract or carrier materially governing runtime closure, reporting/status truth, topology/frame progression, proof/qualification outcomes, event/projection semantics, identity/binding resolution or provider/resolver behavior. A change able to alter how multiple surfaces decide current truth is a core interface change.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 2308,
          "quote": "A core interface includes any shared contract or carrier that materially governs:",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FCore%20Interface%20Migration%20Rule%2FWhat%20Counts%20As%20A%20Core%20Interface",
          "start_line": 2297
        }
      ],
      "key": "core_interface",
      "label": "Core interface"
    },
    {
      "conditions": [],
      "definition": "Evidence supports a claim owner's exact property and required scope; an authorized evaluator supplies evidence rather than a substitute target. UP-001 addresses proof-target identity and weaker-property exclusion, UP-008 separates semantic/evidence/projection bindings, and UP-022 adds assurance-boundary congruence and fresh-constructor qualification.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 2491,
          "quote": "The claim owner supplies the property and required scope; the\nauthorized evaluator supplies evidence, not a substitute target.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FEvidence%20Rules",
          "start_line": 2490
        }
      ],
      "key": "claim_evidence",
      "label": "Constitutional claim evidence"
    },
    {
      "conditions": [],
      "definition": "Constitutional and accepted-design relations defining what a claim means.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 2517,
          "quote": "- **semantic basis**: constitutional and accepted-design relations defining\n  what a claim means;",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FEvidence%20Rules%2FSemantic%2C%20Evidence%2C%20And%20Projection%20Separation%20%28%60STDO-UP-008%60%29",
          "start_line": 2516
        }
      ],
      "key": "semantic_basis",
      "label": "Semantic basis"
    },
    {
      "conditions": [],
      "definition": "Exact artifacts, events, logs, tests and observations used to evaluate a claim.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 2519,
          "quote": "- **evidence basis**: exact artifacts, events, logs, tests, and observations\n  used to evaluate it; and",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FEvidence%20Rules%2FSemantic%2C%20Evidence%2C%20And%20Projection%20Separation%20%28%60STDO-UP-008%60%29",
          "start_line": 2518
        }
      ],
      "key": "evidence_basis",
      "label": "Evidence basis"
    },
    {
      "conditions": [],
      "definition": "A current view derived from admitted semantic and evidence bases.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 2521,
          "quote": "- **state projection**: a current view derived from admitted semantic and\n  evidence bases.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FEvidence%20Rules%2FSemantic%2C%20Evidence%2C%20And%20Projection%20Separation%20%28%60STDO-UP-008%60%29",
          "start_line": 2520
        }
      ],
      "key": "state_projection",
      "label": "State projection"
    },
    {
      "conditions": [],
      "definition": "Generic method-sufficiency qualification uses a fresh competent constructor within declared capability, context and configuration, ordinary method and authority surfaces, a frozen construction result, and an independently authorized evaluator comparing it with the mandatory governing semantic basis. Optional references are evidence, not authority.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 2563,
          "quote": "A fresh competent\nconstructor operates inside a declared capability, context, and configuration\nenvelope using only the declared ordinary method and authority surfaces.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FEvidence%20Rules%2FAssurance-Boundary%20Congruence%20And%20Method%20Qualification%20%28%60STDO-UP-022%60%29",
          "start_line": 2556
        }
      ],
      "key": "method_qualification",
      "label": "Assurance-boundary and method qualification"
    },
    {
      "conditions": [],
      "definition": "Concrete end-to-end Product-owner use cases test operational meaning from intent to realized behavior. Requirements preserve invariant truth, Design structural choice, and Scenarios operational meaning. Scenario bundles or equivalent ordered cases identify exercised boundaries, coherent sequences and expected outcomes at significant steps.",
      "exceptions": [],
      "grounding": [
        {
